const SITE_ORIGINS = [
    'https://animepahe.pw',
    'https://animepahe.com',
    'https://animepahe.org'
];
const DEFAULT_ORIGIN = SITE_ORIGINS[ 0 ];
const MAX_LATEST_PAGE = 4;
const LATEST_PAGE_SIZE = 18;
const EMPTY_HEADERS = [ new KeyValue( '', '' ) ];

function cleanText ( value ) {
    return String( value || '' ).replace( /\s+/g, ' ' ).trim();
