    var origin = originFromUrl( value );

    for ( var index = 0; index < SITE_ORIGINS.length; index++ ) {
        if ( origin.toLowerCase() === SITE_ORIGINS[ index ].toLowerCase() ) {
            return SITE_ORIGINS[ index ];
        }
    }

    return DEFAULT_ORIGIN;
}

function nextOrigin ( currentOrigin ) {
    var normalized = String( currentOrigin || '' ).toLowerCase();

    for ( var index = 0; index < SITE_ORIGINS.length - 1; index++ ) {
        if ( SITE_ORIGINS[ index ].toLowerCase() === normalized ) {
            return SITE_ORIGINS[ index + 1 ];
        }
    }

    return '';
}

function replaceOrigin ( url, newOrigin ) {
    var currentOrigin = originFromUrl( url );
    return currentOrigin
        ? String( url ).replace( currentOrigin, newOrigin )
        : newOrigin + '/';
}

