    return [
        new KeyValue( 'Referer', origin + '/' ),
        new KeyValue( 'Accept-Language', 'en-US,en;q=0.9' )
    ];
}

function apiHeaders ( origin ) {
    return [
        new KeyValue( 'Accept', 'application/json, text/plain, */*' ),
        new KeyValue( 'X-Requested-With', 'XMLHttpRequest' ),
        new KeyValue( 'Referer', origin + '/' ),
        new KeyValue( 'Accept-Language', 'en-US,en;q=0.9' )
    ];
}

function absoluteUrl ( value, origin ) {
    var url = String( value || '' ).trim();
    if ( !url ) return '';
    if ( /^https?:\/\//i.test( url ) ) return url;
    return origin + ( url.charAt( 0 ) === '/' ? url : '/' + url );
}

function parseJsonCandidate ( value ) {
    var raw = String( value || '' ).trim();
    if ( !raw ) return null;

    raw = raw.replace( /^\/\*/, '' ).replace( /\*\/$/, '' ).trim();

    try {
        return JSON.parse( raw );
    } catch ( ignored ) {}

    var objectStart = raw.indexOf( '{' );
    var objectEnd = raw.lastIndexOf( '}' );

    if ( objectStart !== -1 && objectEnd > objectStart ) {
        try {
            return JSON.parse( raw.slice( objectStart, objectEnd + 1 ) );
        } catch ( ignoredObject ) {}
    }

    return null;
}

function responseJson ( ) {
    var candidates = [ ];
    var pre = document.querySelector( 'pre' );

    if ( pre ) {
        candidates.push( pre.textContent );
        candidates.push( pre.innerText );
    }

    Array.from( document.querySelectorAll( 'script' ) ).forEach( function ( script ) {
        candidates.push( script.textContent );
        candidates.push( script.innerText );
    } );

    if ( document.body ) {
        candidates.push( document.body.innerText );
        candidates.push( document.body.textContent );
    }

    if ( document.documentElement ) {
        candidates.push( document.documentElement.innerText );
        candidates.push( document.documentElement.textContent );
    }

    for ( var index = 0; index < candidates.length; index++ ) {
        var parsed = parseJsonCandidate( candidates[ index ] );
        if ( parsed && typeof parsed === 'object' ) {
            return { valid: true, payload: parsed };
        }
    }

    return { valid: false, payload: { data: [ ] } };
}

function queryNumber ( url, key, fallback ) {
    var match = new RegExp( '[?&]' + key + '=([^&#]+)', 'i' ).exec( String( url || '' ) );
    var value = match ? Number( decodeURIComponent( match[ 1 ] ) ) : Number( fallback );
    return isFinite( value ) && value > 0 ? value : Number( fallback );
}

function valueNumber ( values, fallback ) {
    for ( var index = 0; index < values.length; index++ ) {
        var number = Number( values[ index ] );
        if ( isFinite( number ) && number >= 0 ) return number;
    }

    return Number( fallback );
}

function listingLayout ( ) {
    return new Layout(
        new Insets( 10, 10, 10, 10 ),
        1,
        2,
        3,
        1,
        500,
        new Size( 400, 400 ),
        new Ratio( 'width', 4, 11 ),
        new Size( 0, 0 ),
        10,
        10
    );
}

function cleanExistingOutputs ( outputs ) {
    if ( !Array.isArray( outputs ) ) return [ ];

    return outputs.filter( function ( output ) {
        var sectionName = cleanText(
            output && output.section ? output.section.sectionName : ''
        );
        var rows = output && Array.isArray( output.data ) ? output.data : [ ];
        var hasRealRow = rows.some( function ( row ) {
            return cleanText( row && row.title );
        } );

        return Boolean( sectionName || hasRealRow );
    } );
}

function errorRows ( origin, title, description ) {
    return [
        new Data(
            requestFor( '', EMPTY_HEADERS ),
            title,
            description,
            'Web fallback',
            '',
            '',
            '',
            false,
            requestFor( origin + '/', siteHeaders( origin ) ),
            true
        )
    ];
}

var savedData = document.getElementById( 'ketsu-final-data' );
var parsedJson = JSON.parse( savedData.innerHTML || '{}' );
var requestUrl = String(
    parsedJson && parsedJson.request && parsedJson.request.url
        ? parsedJson.request.url
        : location.href
);
var origin = supportedOrigin( requestUrl );
var parsedResponse = responseJson( );
var payload = parsedResponse.payload || { data: [ ] };
var outputs = cleanExistingOutputs( parsedJson.output );
var nextUrl = '';

if ( !parsedResponse.valid ) {
    var retryOrigin = nextOrigin( origin );

    if ( retryOrigin ) {
        nextUrl = replaceOrigin( requestUrl, retryOrigin );
    } else {
        outputs.push(
            new Output(
                CellDesings.wide6,
                Orientation.vertical,
                DefaultLayouts.none,
                Paging.none,
                new Section( 'AnimePahe unavailable', true ),
                listingLayout( ),
                errorRows(
                    SITE_ORIGINS[ 1 ],
                    'Open AnimePahe in WebView',
                    'The API returned a verification or error page. Complete any site check, then refresh the module.'
                )
            )
        );
    }
} else {
    var data = Array.isArray( payload.data ) ? payload.data : [ ];
    var currentPage = valueNumber(
        [
            payload.current_page,
            payload.meta && payload.meta.current_page,
            queryNumber( requestUrl, 'page', 1 )
        ],
        1
    );
    var lastPage = valueNumber(
        [
            payload.last_page,
            payload.meta && payload.meta.last_page,
            currentPage
        ],
        currentPage
    );
    var rows = [ ];
    var seen = { };

    for ( var outputIndex = 0; outputIndex < outputs.length; outputIndex++ ) {
        var oldRows = Array.isArray( outputs[ outputIndex ].data )
            ? outputs[ outputIndex ].data
            : [ ];

        for ( var oldIndex = 0; oldIndex < oldRows.length; oldIndex++ ) {
            var oldLink = oldRows[ oldIndex ] && oldRows[ oldIndex ].link
                ? cleanText( oldRows[ oldIndex ].link.url )
                : '';
            var oldEpisode = cleanText( oldRows[ oldIndex ] && oldRows[ oldIndex ].field1 );
            if ( oldLink ) seen[ oldLink + '|' + oldEpisode ] = true;
        }
    }

    for ( var index = 0; index < data.length; index++ ) {
        var item = data[ index ] || { };
        var session = cleanText( item.anime_session || item.session );
        var title = cleanText( item.anime_title || item.title );
        var episode = cleanText( item.episode || item.number );

        if ( !session || !title ) continue;

        var animeUrl = origin + '/anime/' + encodeURIComponent( session );
        var duplicateKey = animeUrl + '|' + episode;
        if ( seen[ duplicateKey ] ) continue;
        seen[ duplicateKey ] = true;

        var snapshot = absoluteUrl( item.snapshot || item.poster, origin );
        var date = cleanText( item.created_at || item.release_date );
        var type = cleanText( item.type );
        var descriptionParts = [ ];

        if ( episode ) descriptionParts.push( 'Episode ' + episode );
        if ( type ) descriptionParts.push( type );
        if ( date ) descriptionParts.push( date.slice( 0, 10 ) );

        rows.push(
            new Data(
                requestFor( snapshot, siteHeaders( origin ) ),
                title,
                descriptionParts.join( ' • ' ),
                episode ? 'Episode ' + episode : '',
                type,
                date ? date.slice( 0, 10 ) : '',
                '',
                false,
                requestFor( animeUrl, siteHeaders( origin ) ),
                false
            )
        );
    }

    if ( rows.length ) {
        outputs.push(
            new Output(
                CellDesings.wide6,
                Orientation.vertical,
                DefaultLayouts.none,
                Paging.none,
                new Section(
                    currentPage === 1
                        ? 'Latest Releases'
                        : 'Latest Releases • Page ' + String( currentPage ),
                    true
                ),
                listingLayout( ),
                rows
            )
        );
    }

    if ( currentPage < lastPage && currentPage < MAX_LATEST_PAGE ) {
        nextUrl = origin + '/api?m=airing&l=' +
            String( LATEST_PAGE_SIZE ) +
            '&page=' + String( currentPage + 1 );
    } else if ( currentPage < lastPage && currentPage >= MAX_LATEST_PAGE ) {
        outputs.push(
            new Output(
                CellDesings.wide6,
                Orientation.vertical,
                DefaultLayouts.none,
                Paging.none,
                new Section( 'More Releases', true ),
                listingLayout( ),
                errorRows(
                    origin,
                    'Open AnimePahe for older releases',
                    'The module loads four recent API pages to keep the homepage responsive.'
                )
            )
        );
    } else if ( !outputs.length ) {
        outputs.push(
            new Output(
                CellDesings.wide6,
                Orientation.vertical,
                DefaultLayouts.none,
                Paging.none,
                new Section( 'Latest Releases', true ),
                listingLayout( ),
                errorRows(
                    origin,
                    'No releases returned',
                    'AnimePahe returned an empty release page.'
                )
            )
        );
    }
}

var mainPageObject = new MainPage(
    new ModuleRequest( nextUrl, 'get', apiHeaders( supportedOrigin( nextUrl || requestUrl ) ), null ),
    new Extra(
        [ new Commands( '', EMPTY_HEADERS ) ],
        [ new KeyValue( 'latestPage', String( queryNumber( nextUrl || requestUrl, 'page', 1 ) ) ) ]
    ),
    new JavascriptConfig( true, false, '' ),
    outputs
);

savedData.innerHTML = JSON.stringify( mainPageObject );
window.webkit.messageHandlers.EXECUTE_KETSU_ASYNC.postMessage( '' );

    /* JAVASCRIPT ENDS */
} catch ( error ) {
    console.error( error && error.message ? error.message : error );

    try {
        if (
            window.webkit &&
            window.webkit.messageHandlers &&
            window.webkit.messageHandlers.EXECUTE_KETSU_ASYNC
        ) {
            window.webkit.messageHandlers.EXECUTE_KETSU_ASYNC.postMessage( '' );
        }
    } catch ( ignored ) {}
}

